//! Scenario B (spec 11): connection with retry, exponential backoff and a
//! parallel `Connected` state. The same cases (`b_connection/cases.rs`) run
//! against the hand-written machine and against the machine generated by
//! `#[machine]` (milestone M3); `b_connection/drop_oldest.rs` is a machine of
//! its own and runs once.
//!
//! Both versions log the same lines: the macro runs the user's own entry,
//! exit and handler functions, which are the same code.

#[path = "b_connection/drop_oldest.rs"]
mod drop_oldest;

mod hand_written {
    use estado_examples::b_connection as scenario;

    include!("b_connection/cases.rs");
}

mod with_macro {
    use estado_examples::b_connection_macro as scenario;

    include!("b_connection/cases.rs");
}
